package cli

import (
	"context"
	"errors"
	"fmt"
	"io"
	"strings"

	"github.com/go-git/go-git/v6/plumbing"
	"github.com/spf13/cobra"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/remote"
	"github.com/entireio/cli/cmd/entire/cli/gitremote"
	"github.com/entireio/cli/internal/coreapi"
)

// explainRepoRef is a parsed `explain --repo` value: either an owner/name slug
// (possibly given with a gh/ prefix) or a raw repo ULID that still needs a
// control-plane lookup to become owner/name.
type explainRepoRef struct {
	owner, repo string // owner/name form (lowercased)
	repoID      string // bare-ULID form
}

// parseExplainRepoFlag parses the --repo flag value. Accepted shapes:
// `owner/name`, `gh/owner/name` (leading slash optional), or a bare repo ULID.
// owner/name reuse the GitHub charset validation of the mirror clone-ref
// parser and come back lowercased, matching what the control plane persists.
func parseExplainRepoFlag(value string) (explainRepoRef, error) {
	v := strings.TrimSpace(value)
	if v == "" {
		return explainRepoRef{}, errors.New("--repo requires a value: owner/name, gh/owner/name, or a repo ID")
	}
	if strings.Contains(v, "/") {
		// Normalize owner/name to the gh/owner/name clone-ref shape so
		// parseMirrorCloneRef's charset validation applies to both forms.
		ref := strings.TrimPrefix(v, "/")
		if !strings.HasPrefix(ref, "gh/") {
			ref = "gh/" + ref
		}
		_, owner, repo, err := parseMirrorCloneRef(ref)
		if err != nil {
			return explainRepoRef{}, fmt.Errorf("invalid --repo %q: expected owner/name, gh/owner/name, or a repo ID: %w", value, err)
		}
		return explainRepoRef{owner: owner, repo: repo}, nil
	}
	if !looksLikeULID(v) {
		return explainRepoRef{}, fmt.Errorf("invalid --repo %q: expected owner/name, gh/owner/name, or a repo ID (ULID)", value)
	}
	return explainRepoRef{repoID: v}, nil
}

// resolveExplainRepoID resolves a raw repo ULID to its owner/name via the
// control plane's by-id lookup (the same call `entire repo get <ulid>` uses).
// A clusterFlag naming a cluster in a different federation dials that
// cluster's core instead of the active context's, matching how the placement
// lookup routes (see listPullablePlacements).
func resolveExplainRepoID(cmd *cobra.Command, repoID, clusterFlag string) (owner, repo string, err error) {
	runWithCore, err := coreRunnerForCluster(clusterFlag)
	if err != nil {
		return "", "", err
	}
	var fullName string
	err = runWithCore(cmd, func(ctx context.Context, c *coreapi.Client) error {
		r, err := c.GetRepo(ctx, coreapi.GetRepoParams{RepoId: repoID})
		if err != nil {
			if isCoreNotFound(err) {
				return fmt.Errorf("no repository with ID %q visible from your login", repoID)
			}
			return fmt.Errorf("look up repository %q: %w", repoID, err)
		}
		fullName = r.FullName.Or("")
		return nil
	})
	if err != nil {
		return "", "", err
	}
	owner, repo, ok := strings.Cut(strings.ToLower(fullName), "/")
	if !ok || owner == "" || repo == "" {
		return "", "", fmt.Errorf("repository %q has an unexpected full name %q (want owner/name)", repoID, fullName)
	}
	return owner, repo, nil
}

// explainRepoIsCurrent reports whether owner/repo names the same repository as
// the cwd worktree's origin remote (handles ssh, https, and entire:// mirror
// URL forms). --repo is GitHub-scoped (gh/owner/name), so a non-GitHub origin
// with a coincidentally matching owner/name must not count as the current
// repo. Best-effort: any lookup or parse failure returns false, so explain
// proceeds with the cross-repo fetch path.
func explainRepoIsCurrent(ctx context.Context, owner, repo string) bool {
	curForge, curOwner, curRepo, err := gitremote.ResolveRemoteRepo(ctx, "origin")
	if err != nil || curForge != "gh" {
		return false
	}
	return strings.EqualFold(curOwner, owner) && strings.EqualFold(curRepo, repo)
}

// resolveExplainRepoFetchURL resolves the entire:// mirror URL to fetch a
// foreign repo's checkpoint ref from: pullable placements via the core API
// (the same authority `repo clone` uses), then the shared placement picker
// with explain-specific wording and the --cluster escape hatch.
func resolveExplainRepoFetchURL(cmd *cobra.Command, owner, repo, clusterFlag string) (string, error) {
	placements, err := listPullablePlacements(cmd, owner, repo, clusterFlag)
	if err != nil {
		return "", err
	}
	if len(placements) == 0 {
		return "", fmt.Errorf("no mirror found for /gh/%s/%s; cross-repo explain fetches checkpoints from the repo's Entire mirror", owner, repo)
	}
	chosen, err := selectPlacement(cmd, placements, clusterFlag, placementPicker{
		selector: "--cluster",
		title:    "This repo is mirrored on more than one cluster — pick one to fetch the checkpoint from",
		action:   "Explain",
	})
	if err != nil {
		return "", err
	}
	// chosen.ClusterHost is server-provided but interpolated into the entire://
	// URL like a user-supplied --cluster, so apply the same anti-token-leak
	// guard before building it (see repo clone).
	if err := validateClusterHost(chosen.ClusterHost); err != nil {
		return "", fmt.Errorf("mirror has an invalid cluster host %q: %w", chosen.ClusterHost, err)
	}
	return mirrorCloneURL(chosen.ClusterHost, owner, repo), nil
}

// prepareCrossRepoExplain resolves --repo/--cluster and, when the target repo
// differs from the cwd repo, fetches the checkpoint's per-checkpoint ref from
// that repo's Entire mirror into the cwd repo's object store. After a nil
// return, the normal explain flow resolves the checkpoint as if it were local.
// When --repo names the cwd repo it is a no-op (behavior identical to no flag).
func prepareCrossRepoExplain(cmd *cobra.Command, repoFlag, clusterFlag, target string) error {
	ref, err := parseExplainRepoFlag(repoFlag)
	if err != nil {
		return err
	}
	// Everything past flag parsing is a runtime failure (network, git), not a
	// usage mistake — don't dump usage text on it.
	cmd.SilenceUsage = true
	owner, repoName := ref.owner, ref.repo
	if ref.repoID != "" {
		owner, repoName, err = resolveExplainRepoID(cmd, ref.repoID, clusterFlag)
		if err != nil {
			return err
		}
	}
	if explainRepoIsCurrent(cmd.Context(), owner, repoName) {
		return nil
	}
	// A prefix cannot name a per-checkpoint ref, so cross-repo needs the full ID.
	cid, err := id.NewCheckpointID(target)
	if err != nil {
		return fmt.Errorf("--repo requires a full checkpoint ID (12-char hex or 26-char ULID); a prefix cannot be resolved cross-repo: %w", err)
	}
	url, err := resolveExplainRepoFetchURL(cmd, owner, repoName, clusterFlag)
	if err != nil {
		return err
	}
	return fetchCrossRepoCheckpoint(cmd.Context(), cmd.ErrOrStderr(), url, owner+"/"+repoName, cid)
}

// fetchCrossRepoCheckpoint fetches cid's per-checkpoint ref
// (refs/entire/checkpoints/<shard>/<id>) from url into the cwd repo's object
// store. Separated from URL resolution so tests can exercise the fetch +
// explain flow against a file:// remote without the core API or
// git-remote-entire.
func fetchCrossRepoCheckpoint(ctx context.Context, errW io.Writer, url, ownerRepo string, cid id.CheckpointID) error {
	refName, err := checkpoint.RefName(cid)
	if err != nil {
		// Defensive only: cid is already validated by the caller.
		return err //nolint:wrapcheck // RefName's error is self-describing
	}
	stop := startSpinner(errW, "Fetching checkpoint from "+ownerRepo)
	fetchErr := remote.FetchCheckpointRefFrom(ctx, url, refName)
	stop(fetchErr == nil)
	if fetchErr == nil {
		return nil
	}
	if errors.Is(fetchErr, plumbing.ErrReferenceNotFound) {
		return fmt.Errorf("checkpoint %s not found in the mirror for %s; repos using the legacy branch-based checkpoint store (or an external checkpoint_remote) are not supported cross-repo yet", cid, ownerRepo)
	}
	return fmt.Errorf("fetch checkpoint %s from %s: %w", cid, ownerRepo, fetchErr)
}

package remote

import (
	"bytes"
	"context"
	"fmt"
	"log/slog"
	"os/exec"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/settings"

	"github.com/go-git/go-git/v6/plumbing"
)

// WriteProbeFetchBudget bounds the on-demand ref fetch performed by a
// BACKFILL's absence probe. Write paths run inside git hooks (post-commit,
// stop-time finalize) where a dead network must not stall the user's
// workflow for the read path's full fetch window; combined with the
// per-store failure memo in the git-refs store, a loop over N checkpoints
// pays a dead network once, briefly.
const WriteProbeFetchBudget = 15 * time.Second

// readFetchTimeout bounds the interactive read-path fetch (unchanged from
// the historical FetchCheckpointRef behavior).
const readFetchTimeout = 2 * time.Minute

// CheckpointFetchTarget returns the git remote (URL or name) that checkpoint
// data is fetched from. It prefers the effective URL resolved by FetchURL,
// which is the source of truth for checkpoint fetch location. If URL
// resolution fails, it falls back to the origin remote name so callers can
// still attempt a fetch.
func CheckpointFetchTarget(ctx context.Context) string {
	target, _ := checkpointFetchTarget(ctx)
	return target
}

// checkpointFetchTarget is CheckpointFetchTarget plus whether the target is
// authoritative for checkpoint refs (see fetchURLAuthoritative). The bare
// "origin" fallbacks are non-authoritative: they exist so a fetch can still
// be attempted, not to certify where checkpoint refs live.
func checkpointFetchTarget(ctx context.Context) (string, bool) {
	url, authoritative, err := fetchURLAuthoritative(ctx)
	if err == nil && url != "" {
		return url, authoritative
	}
	return "origin", false
}

// FetchCheckpointRef fetches a single per-checkpoint ref
// (refs/entire/checkpoints/<shard>/<id>) from the checkpoint remote into the
// local ref of the same name, so the git-refs store can resolve a checkpoint
// written on another machine.
//
// Contract — absence is distinguishable from failure:
//   - The remote genuinely lacking the ref returns an error wrapping
//     plumbing.ErrReferenceNotFound (probed via ls-remote before fetching,
//     because `git fetch` of a missing refspec fails indistinguishably from a
//     transport error). Store probes classify this as "checkpoint not found",
//     which write routing may legitimately act on.
//   - Any transport-level failure (probe or fetch) is surfaced as a real
//     error, never mapped to absence — a false "absent" would misdirect a
//     backfill onto another backend instead of retrying.
//   - A repository with no git remotes at all and no checkpoint_remote
//     configured also returns an error wrapping plumbing.ErrReferenceNotFound
//     without probing: there is no remote that could host the ref.
func FetchCheckpointRef(ctx context.Context, ref plumbing.ReferenceName) error {
	ctx, cancel := context.WithTimeout(ctx, readFetchTimeout)
	defer cancel()

	fetchTarget, authoritative := checkpointFetchTarget(ctx)

	// A fully local repository — no git remotes at all and no
	// checkpoint_remote configured — has no remote that could host checkpoint
	// refs, so the ref's local absence is the final verdict. Without this,
	// the origin-name fallback below probes a remote git cannot resolve
	// ("'origin' does not appear to be a git repository", exit 128) and a
	// remoteless repo is misreported as a transport outage. Absence is only
	// ever classified on positive evidence; each escape below keeps today's
	// hard-failure probe:
	//   - dead caller context: every subprocess fails for reasons that say
	//     nothing about the repository
	//   - unreadable settings: a configured checkpoint remote cannot be
	//     ruled out
	//   - checkpoint_remote key present in any form, valid or malformed
	//     (see settings.HasCheckpointRemoteKey for why key presence, not
	//     GetCheckpointRemote, is the signal)
	//   - any remote listed, or the listing itself failing: checkpoint refs
	//     are pushed to whatever remote the pre-push hook fires for, so a
	//     repo with only non-origin remotes is NOT remoteless
	// The skipped-guard cases surface through the ordinary probe paths: a
	// missing origin fails the ls-remote probe as a transport error, and an
	// origin that merely lacks the ref hits the fallback-emptiness refusal
	// below — neither classifies as absence.
	if fetchTarget == originRemote && !authoritative && ctx.Err() == nil {
		s, loadErr := settings.Load(ctx)
		switch {
		case loadErr != nil:
			logging.Warn(ctx, "checkpoint probe: settings unreadable; cannot rule out a configured checkpoint remote, probing anyway",
				slog.String("error", loadErr.Error()))
		case !s.HasCheckpointRemoteKey() && repoHasNoRemotes(ctx):
			logging.Debug(ctx, "checkpoint probe: repository has no git remotes; classifying ref as absent",
				slog.String("ref", ref.String()))
			return fmt.Errorf("checkpoint ref %s: repository has no git remotes to fetch from: %w", ref, plumbing.ErrReferenceNotFound)
		}
	}

	return probeAndFetchCheckpointRef(ctx, fetchTarget, authoritative, ref)
}

// FetchCheckpointRefFrom fetches a single per-checkpoint ref from an explicitly
// named remote URL (rather than the current repo's resolved checkpoint remote)
// into the local ref of the same name. The URL is treated as authoritative for
// checkpoint refs: an empty ls-remote probe returns an error wrapping
// plumbing.ErrReferenceNotFound, distinguishable from transport failures (see
// FetchCheckpointRef's contract). Used by cross-repo explain, which fetches a
// checkpoint ref from another repo's Entire mirror into the cwd repo's object
// store.
func FetchCheckpointRefFrom(ctx context.Context, url string, ref plumbing.ReferenceName) error {
	ctx, cancel := context.WithTimeout(ctx, readFetchTimeout)
	defer cancel()
	return probeAndFetchCheckpointRef(ctx, url, true, ref)
}

// probeAndFetchCheckpointRef is the shared probe+fetch core: ls-remote probe
// (absence detection), then a single-refspec fetch with NoTags. authoritative
// controls whether an empty probe classifies as absence
// (plumbing.ErrReferenceNotFound) or is refused (see FetchCheckpointRef).
func probeAndFetchCheckpointRef(ctx context.Context, fetchTarget string, authoritative bool, ref plumbing.ReferenceName) error {
	out, err := LsRemoteInDir(ctx, "", fetchTarget, ref.String())
	if err != nil {
		// Redact: fetchTarget can be a remote URL with embedded credentials
		// (CI origin URLs), and this error is logged and shown to users.
		return fmt.Errorf("probe checkpoint ref %s on %s: %w", ref, RedactURL(fetchTarget), err)
	}
	if len(bytes.TrimSpace(out)) == 0 {
		if !authoritative {
			// The probe hit an origin FALLBACK while a checkpoint_remote is
			// configured (or undeterminable) — a remote that may simply never
			// host the configured checkpoint refs. Emptiness there proves
			// nothing; classifying it as absence would silently drop backfills
			// for checkpoints that exist on the real checkpoint remote.
			return fmt.Errorf("checkpoint ref %s not visible on fallback remote %s, and the configured checkpoint remote could not be resolved; refusing to treat this as absence", ref, RedactURL(fetchTarget))
		}
		return fmt.Errorf("checkpoint ref %s not found on %s: %w", ref, RedactURL(fetchTarget), plumbing.ErrReferenceNotFound)
	}

	refSpec := "+" + ref.String() + ":" + ref.String()
	if fetchOut, err := Fetch(ctx, FetchOptions{
		Remote:   fetchTarget,
		RefSpecs: []string{refSpec},
		NoTags:   true,
	}); err != nil {
		// Fold git's own output into the error (redacted): a bare
		// "exit status 128" is undebuggable in hook Warn logs.
		msg := strings.TrimSpace(string(fetchOut))
		msg = strings.ReplaceAll(msg, fetchTarget, RedactURL(fetchTarget))
		if msg != "" {
			return fmt.Errorf("fetch checkpoint ref %s from %s: %s: %w", ref, RedactURL(fetchTarget), msg, err)
		}
		return fmt.Errorf("fetch checkpoint ref %s from %s: %w", ref, RedactURL(fetchTarget), err)
	}
	return nil
}

// repoHasNoRemotes reports whether the repository at the current directory
// definitively has no git remotes configured. Only a successful, empty
// `git remote` listing counts as proof; any error (dead context, missing git
// binary, not a repository) returns false so the caller falls through to the
// probe instead of classifying absence off an undifferentiated failure.
func repoHasNoRemotes(ctx context.Context) bool {
	out, err := exec.CommandContext(ctx, "git", "remote").Output()
	return err == nil && len(bytes.TrimSpace(out)) == 0
}

// HookCheckpointRefFetcher returns the write-probe fetcher for git-hook
// contexts (post-commit attribution, stop-time transcript finalize): the
// bounded budget plus BatchMode SSH, so a passphrase-protected key can never
// prompt — or invisibly hang — inside a hook the user's git command is
// waiting on.
func HookCheckpointRefFetcher() func(context.Context, plumbing.ReferenceName) error {
	bounded := BoundedCheckpointRefFetcher(WriteProbeFetchBudget)
	return func(ctx context.Context, ref plumbing.ReferenceName) error {
		return bounded(WithNonInteractiveSSH(ctx), ref)
	}
}

// BoundedCheckpointRefFetcher returns a RefFetchFunc-shaped fetcher whose
// per-call budget is capped at d, for wiring into write-path checkpoint
// stores (see WriteProbeFetchBudget).
func BoundedCheckpointRefFetcher(d time.Duration) func(context.Context, plumbing.ReferenceName) error {
	return func(ctx context.Context, ref plumbing.ReferenceName) error {
		ctx, cancel := context.WithTimeout(ctx, d)
		defer cancel()
		return FetchCheckpointRef(ctx, ref)
	}
}

