95	//  3. Positional that fails as a checkpoint prefix falls back to commit-ref
96	//     resolution (mirrors runExplainAuto).
97	func resolveExplainCheckpointID(ctx context.Context, errW io.Writer, opts explainExportOptions) (id.CheckpointID, *explainCheckpointLookup, error) {
