173	// Invariant: on every error return the lookup is nil (any lookup created
174	// along the way is closed internally), so callers may drop the lookup slot
175	// without closing it when err != nil.
176	func resolveCheckpointFromCommitRef(ctx context.Context, errW io.Writer, commitRef string) (id.CheckpointID, *explainCheckpointLookup, error) {
177		repo, err := openRepository(ctx)
178		if err != nil {
179			return id.CheckpointID(""), nil, fmt.Errorf("not a git repository: %w", err)
180		}
