193			}
194			return id.CheckpointID(""), nil, fmt.Errorf("%w: %s: %w", errExportTargetNotCommit, commitRef, err)
195		}
196		commit, err := repo.CommitObject(hash)
197		if err != nil {
198			return id.CheckpointID(""), nil, fmt.Errorf("failed to read commit: %w", err)
199		}
200		cpID, found := trailers.ParseCheckpoint(commit.Message)
201		if !found {
202			return id.CheckpointID(""), nil, fmt.Errorf("commit %s has no Entire-Checkpoint trailer", commit.Hash)
203		}
204		lookup, lookupErr := newExplainCheckpointLookup(ctx)
205		if lookupErr != nil {
206			return id.CheckpointID(""), nil, lookupErr
207		}
208	
209		// If the trailer points at a checkpoint we don't have locally, do the
210		// same remote-fetch retry the prefix path uses; otherwise downstream
211		// metadata reads would fail with an immediate "not found".
212		if !lookupHasCheckpoint(lookup, cpID) {
213			matches, fresh := matchCheckpointPrefixWithRemoteFallback(ctx, errW, lookup, cpID.String())
214			if fresh != lookup {
215				_ = lookup.Close()
216				lookup = fresh
217			}
218			if len(matches) != 1 {
219				// The commit resolved and its trailer parsed; the checkpoint is
220				// simply not obtainable here. Failing now with the linkage beats
221				// succeeding and letting a downstream read die with a bare
222				// "checkpoint not found" that misdirects the user toward the
223				// checkpoint ID when the problem is availability (offline,
224				// unfetchable remote, or genuinely gone).
225				_ = lookup.Close()
226				return id.CheckpointID(""), nil, fmt.Errorf("commit %s references checkpoint %s, which is not available locally and could not be fetched from the remote", commitRef, cpID)
227			}
228		}
229		return cpID, lookup, nil
230	}
231	
232	// lookupHasCheckpoint reports whether cpID is in the lookup's local committed
233	// list. Callers use this before triggering a remote-fetch retry.
234	func lookupHasCheckpoint(lookup *explainCheckpointLookup, cpID id.CheckpointID) bool {
235		for _, info := range lookup.committed {
236			if info.CheckpointID == cpID {
237				return true
238			}
239		}
240		return false

